def _validate_retag_source_archive_layout(source_dir: Path) -> None:
    """Reject archive source content that a retag cannot safely account for."""
    if not source_dir.exists():
        return
    if source_dir.is_symlink() or not source_dir.is_dir():
        raise ValueError(f"invalid retag archive source: {source_dir}")
    for month_dir in source_dir.iterdir():
        if (
            month_dir.is_symlink()
            or not month_dir.is_dir()
            or not month_dir.name.startswith("month=")
        ):
            raise ValueError(
                f"invalid retag archive layout: expected month=*/entries.parquet, found {month_dir}"
            )
        children = list(month_dir.iterdir())
        expected = month_dir / "entries.parquet"
        if (
            len(children) != 1
            or children[0] != expected
            or expected.is_symlink()
            or not expected.is_file()
        ):
            raise ValueError(
                f"invalid retag archive layout: expected only {expected}"
            )


def _validate_retag_source_entries(entries: list[dict[str, Any]], old: str, *, path: Path) -> None:
    """Require every source record to belong to the slug being repaired."""
    for index, entry in enumerate(entries, start=1):
        project = entry.get("project")
        if not isinstance(project, str) or not project.strip():
            raise ValueError(
                f"invalid retag source record at {path}:{index}: project must be a non-empty string"
            )
        if paths_mod.slugify_project(project) != old:
            raise ValueError(
                f"invalid retag source record at {path}:{index}: project '{project}' does not match '{old}'"
            )


def _preflight_retag_source_archive(source_dir: Path, old: str) -> None:
    for parquet_path in sorted(source_dir.glob("month=*/entries.parquet")):
        _validate_retag_source_entries(
            archive_mod.read_parquet(parquet_path, hive_partitioning=False),
            old,
            path=parquet_path,
        )


def _json_safe_archive_value(value: Any) -> Any:
    """Convert DuckDB's datetime values back to JSONL-safe archive payload values."""
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, list):
        return [_json_safe_archive_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _json_safe_archive_value(item) for key, item in value.items()}
    return value


def _retag_archive_tier(home: Path, old: str, new: str, *, dry_run: bool) -> list[dict[str, Any]]:
    source_dir = home / "archive" / f"project={old}"
    target_dir = home / "archive" / f"project={new}"
    months = {
        path.parent.name
        for project_dir in (source_dir, target_dir)
        if project_dir.exists()
        for path in project_dir.glob("month=*/entries.parquet")
    }
    reports: list[dict[str, Any]] = []
    for month in sorted(months):
        source = source_dir / month / "entries.parquet"
        target = target_dir / month / "entries.parquet"
        source_entries = archive_mod.read_parquet(source, hive_partitioning=False)
        target_entries = archive_mod.read_parquet(target, hive_partitioning=False)
