pub fn review_approve_with(
    conn: &mut Connection,
    proposal_id: &str,
    reviewed_by: &str,
    opts: ReviewOptions,
) -> Result<ReviewOutcome> {
    let decisions = match opts.decisions {
        Some(d) => d,
        None => load_accept_all_decisions(conn, proposal_id)?,
    };
    let result = resolve_proposal(
        conn,
        proposal_id,
        &decisions,
        None,
        ResolveOptions {
            auto_approve: false,
            // Agent surface (CLI `proposals review` / MCP / internal API):
            // never confers the human tier (spec §3.7-A) — resolves at agent
            // tier and writes `approved_at_agent_tier`.
            human_surface: false,
            reviewed_by: Some(reviewed_by.to_string()),
            embed_profile: opts.embed_profile,
            entry_embeddings: opts.entry_embeddings,
            audit: opts.audit,
            // Honour the on-disk `wiki.deposit_default_tier`, like every other
            // resolve path (desk, CLI approve, legacy shim, librarian). Without
            // it the resolver falls back to the shipped DEFAULT_DEPOSIT_TIER and
            // an operator who set `fact` would silently get deposit entries in
            // `wisdom` — but only when they approved through a review surface.
            // Lock-holding callers preload it (`ReviewOptions::deposit_default_tier`)
            // so no filesystem I/O happens under their mutex.
            deposit_default_tier: Some(
                opts.deposit_default_tier
                    .unwrap_or_else(crate::config::BrainConfig::deposit_default_tier_on_disk),
            ),
        },
    )?;
    Ok(ReviewOutcome {
        proposal_id: proposal_id.to_string(),
        status: result.proposal_status,
        committed: result.committed.len(),
        conflicts: result.conflicts,
        reviewed_by: reviewed_by.to_string(),
